export const categories=[['all','全部作品'],['image-generation','模型生图'],['procedural-image','代码图像'],['coding-motion','代码动效'],['interactive','交互解释']];
export function filterCases(items,{category='all',query=''}={}){const ts=query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);return items.filter(c=>(category==='all'||c.category===category)&&ts.every(t=>[c.title,c.summary,c.engine,c.model,c.useCase,...c.tags].join(' ').toLocaleLowerCase().includes(t)))}
export function validateCase(c){let e=[];for(let k of['id','title','category','method','engine','model','poster','artifact','provenance','rights','verification'])if(!c[k])e.push(k);if(c.category==='image-generation'&&c.method!=='image-model')e.push('method mismatch');for(let k of['poster','artifact','provenance'])if(c[k]&&(!/^[\w./-]+$/.test(c[k])||c[k].startsWith('/')||c[k].split('/').includes('..')))e.push('unsafe path');return e}
